import{test}from'node:test';import assert from'node:assert/strict';import{Window}from'happy-dom';
import type{AppRecord,Bootstrap}from'../lib/types';
const window:any=new Window({url:'https://qingdan.test/'});const g=globalThis as any;
for(const key of ['window','document','navigator','location','history','HTMLElement','HTMLInputElement','HTMLTextAreaElement','HTMLSelectElement','Event','CustomEvent','MouseEvent','KeyboardEvent','FocusEvent','MutationObserver','sessionStorage','localStorage'])Object.defineProperty(g,key,{value:(window as any)[key],configurable:true,writable:true});
g.requestAnimationFrame=(fn:FrameRequestCallback)=>setTimeout(()=>fn(Date.now()),0);g.cancelAnimationFrame=clearTimeout;g.IS_REACT_ACT_ENVIRONMENT=true;
// This DOM simulator has no layout engine. Rects represent visibility only, never visual QA.
(window.HTMLElement.prototype as any).getClientRects=function(){return this.hidden?[]:[{width:100,height:30}]};
const React=await import('react');const{createRoot}=await import('react-dom/client');const{act}=React;const{default:Workspace}=await import('../app/workspace');const{localDate}=await import('../lib/types');const{draftStore}=await import('../lib/client-storage');
const user={userId:'ui-fixture',displayName:'UI测试',email:'fixture@example.test'};
function fixture(){const records:AppRecord[]=[{id:'inbox:'+user.userId,ownerId:user.userId,kind:'list',listId:null,data:{title:'收集箱',sections:[],color:'#4878e8'},revision:1,updatedAt:new Date().toISOString(),deleted:false,role:'owner'},{id:'task-ui',ownerId:user.userId,kind:'task',listId:'inbox:'+user.userId,data:{title:'明确定义的示例任务',description:'原始描述',status:'open',taskType:'task',listId:'inbox:'+user.userId,priority:2,dueDate:localDate(),checkItems:[{id:'a',title:'第一项',done:false},{id:'b',title:'第二项',done:false}],tags:[]},revision:1,updatedAt:new Date().toISOString(),deleted:false,role:'owner'}];return{records,history:[],attachments:[],members:[],user,serverTime:new Date().toISOString()}as Bootstrap;}
const settle=async()=>{await act(async()=>{await new Promise(r=>setTimeout(r,5))})};
function type(el:HTMLInputElement|HTMLTextAreaElement,value:string){const proto=el.tagName==='TEXTAREA'?window.HTMLTextAreaElement.prototype:window.HTMLInputElement.prototype;Object.getOwnPropertyDescriptor(proto,'value')!.set!.call(el,value);el.dispatchEvent(new window.Event('input',{bubbles:true}));}
function click(el:Element|null){assert.ok(el);(el as HTMLElement).click();}
function btn(text:string){return Array.from(document.querySelectorAll<HTMLButtonElement>('button')).find(b=>b.textContent?.trim()===text)||null;}
function setupApi(state:Bootstrap,calls:any[]=[]){for(const key of Object.keys(localStorage))if(key.startsWith('qingdan:queue:')&&key.includes(':'+user.userId+':'))localStorage.removeItem(key);draftStore.removeItem('qingdan:draft:ui-fixture:task-ui');g.fetch=async(path:string,init?:RequestInit)=>{const body=init?.body?JSON.parse(init.body as string):undefined;if(body)calls.push(body);if(path==='/api/reminders')return Response.json({alerts:[]});if(path==='/api/data'&&!body)return Response.json(state);if(path==='/api/data'&&body?.operation==='upsert'){const existing=state.records.find(r=>r.id===body.id);if(existing&&body.expectedRevision!==existing.revision)return Response.json({error:'记录版本冲突'},{status:409});const record:AppRecord={id:body.id,ownerId:user.userId,kind:body.kind,listId:body.data.listId||null,data:body.data,revision:(existing?.revision||0)+1,updatedAt:new Date().toISOString(),deleted:!!body.deleted,role:'owner'};state.records=[record,...state.records.filter(r=>r.id!==record.id)];return Response.json({record,related:[]})}if(path==='/api/data'&&['complete','undoComplete'].includes(body?.operation)){const existing=state.records.find(r=>r.id===body.id)!;const record={...existing,revision:existing.revision+1,data:{...existing.data,status:body.operation==='undoComplete'?'open':body.status||'done',completionMutation:body.operation==='undoComplete'?'':'ui-mutation'}};state.records=state.records.map(r=>r.id===record.id?record:r);return Response.json({records:[record],record})}throw new Error('Test forbids unmocked network: '+path)};}

test('workspace renders core task surface, details/checklist, focus/search and settings dialog',async()=>{const state=fixture();setupApi(state);const host=document.createElement('div');(document.body as any).append(host);const root=createRoot(host as any);try{await act(async()=>{root.render(<Workspace user={user}/>)});await settle();assert.equal(host.querySelector('.workspace-header h1')?.textContent,'今天');assert.equal(host.querySelectorAll('.task-row').length,1);await act(async()=>click(host.querySelector('.task-body')));assert.equal(host.querySelector('.detail-title')?.textContent,'明确定义的示例任务');const checks=Array.from(host.querySelectorAll<HTMLInputElement>('.check-item input[type=checkbox]'));assert.equal(checks.length,2);await act(async()=>{click(checks[0]);click(checks[1])});await settle();assert.deepEqual(state.records.find(r=>r.id==='task-ui')?.data.checkItems?.map(c=>c.done),[true,true]);await act(async()=>click(host.querySelector('button[aria-label="专注"]')));assert.ok(host.querySelector('.focus-wrapper'));await act(async()=>document.body.dispatchEvent(new window.KeyboardEvent('keydown',{key:'/',bubbles:true})));await settle();assert.ok(host.querySelector('#search'));assert.equal(host.querySelector('.workspace-header h1')?.textContent,'今天');await act(async()=>click(host.querySelector('.rail-bottom button[title="设置"]')));assert.equal(document.querySelector('.modal')?.getAttribute('role'),'dialog');await act(async()=>document.dispatchEvent(new window.KeyboardEvent('keydown',{key:'Escape',bubbles:true})));assert.equal(document.querySelector('.modal'),null)}finally{await act(async()=>root.unmount());host.remove();window.happyDOM.abort();}});

test('quick add performs real mocked record write and retains Chinese composition until Enter',async()=>{const state=fixture();setupApi(state);const host=document.createElement('div');(document.body as any).append(host);const root=createRoot(host as any);try{await act(async()=>root.render(<Workspace user={user}/>));await settle();const textarea=host.querySelector<HTMLTextAreaElement>('.quick-add textarea')!;await act(async()=>type(textarea,'测试新的任务'));assert.equal(textarea.value,'测试新的任务');await act(async()=>textarea.dispatchEvent(new window.KeyboardEvent('keydown',{key:'Enter',isComposing:true,bubbles:true})));assert.equal(state.records.filter(r=>r.kind==='task').length,1);await act(async()=>textarea.dispatchEvent(new window.KeyboardEvent('keydown',{key:'Enter',bubbles:true})));await settle();assert.equal(state.records.filter(r=>r.kind==='task').length,2);assert.ok(state.records.some(r=>r.data.title==='测试新的任务'));assert.equal(textarea.value,'')}finally{await act(async()=>root.unmount());host.remove();window.happyDOM.abort();}});

test('calendar mode exposes real date views, layer controls and drag-selected range modal',async()=>{const state=fixture();setupApi(state);const host=document.createElement('div');(document.body as any).append(host);const root=createRoot(host as any);try{await act(async()=>root.render(<Workspace user={user}/>));await settle();await act(async()=>click(host.querySelector('button[aria-label="日历"]')));assert.equal(host.querySelectorAll('.day-cell').length,42);const select=host.querySelector('select[aria-label="日历视图"]') as unknown as HTMLSelectElement;await act(async()=>{select.value='week';select.dispatchEvent(new window.Event('change',{bubbles:true}))});assert.equal(host.querySelectorAll('.time-row').length,24);assert.ok(host.querySelector('select[aria-label="时间刻度缩放"]'));assert.ok(host.querySelector('.calendar-layer-menu'));const cell=host.querySelector<HTMLElement>('.time-row:nth-child(12)>div')!;(cell as any).getBoundingClientRect=()=>({top:100,width:100,height:52,left:0,right:100,bottom:152});await act(async()=>cell.dispatchEvent(new window.PointerEvent('pointerdown',{button:0,clientY:110,clientX:30,bubbles:true})));await act(async()=>window.dispatchEvent(new window.PointerEvent('pointerup',{button:0,clientY:162,clientX:30,bubbles:true})));assert.ok(document.querySelector('.modal'));assert.match(document.querySelector('.modal .form-help')?.textContent||'',/分钟/);await act(async()=>document.dispatchEvent(new window.KeyboardEvent('keydown',{key:'Escape',bubbles:true})));assert.equal(document.querySelector('.modal'),null)}finally{await act(async()=>root.unmount());host.remove();window.happyDOM.abort();}});

test('settings identity, JSON/CSV/ICS export labels and module navigation remain available',async()=>{const state=fixture();setupApi(state);const host=document.createElement('div');(document.body as any).append(host);const root=createRoot(host as any);try{await act(async()=>root.render(<Workspace user={user}/>));await settle();for(const label of ['四象限','习惯','统计','倒数日','模板']){await act(async()=>click(host.querySelector('button[aria-label="'+label+'"]')));assert.equal(host.querySelector('.workspace-header h1')?.textContent,label)}await act(async()=>click(host.querySelector('.rail-bottom button[title="设置"]')));await act(async()=>click(btn('导入与导出')));assert.ok(btn('导出 JSON'));assert.ok(btn('导出 CSV'));assert.ok(btn('导出 ICS'));assert.ok(document.querySelector('input[type=file][accept*=".csv"]'));await act(async()=>click(btn('账号与同步')));assert.match(document.querySelector('.account-card')?.textContent||'',/fixture@example.test/)}finally{await act(async()=>root.unmount());host.remove();window.happyDOM.abort();}});

test('rich editor supports real bold formatting and Markdown serialization',async()=>{const{default:RichEditor}=await import('../app/rich-editor');const host=document.createElement('div');(document.body as any).append(host);const root=createRoot(host as any);let markdown='原始描述';try{await act(async()=>root.render(<RichEditor value={markdown} editable version={1} dirty={false} onChange={value=>{markdown=value}} onBlur={()=>{}}/>));await settle();const body=host.querySelector<HTMLElement>('.rich-body')!;assert.ok(body);assert.match(body.textContent||'',/原始描述/);await act(async()=>{body.focus();body.dispatchEvent(new window.KeyboardEvent('keydown',{key:'a',code:'KeyA',ctrlKey:true,bubbles:true}))});await act(async()=>click(host.querySelector('button[aria-label="加粗"]')));await settle();assert.match(host.querySelector('.rich-body')?.innerHTML||'',/<strong>/);assert.match(markdown,/\*\*原始描述\*\*/)}finally{await act(async()=>root.unmount());host.remove();window.happyDOM.abort();}});

test('unsupported persisted and dirty raw HTML retain table cells and image URLs across rich-mode attempt',async()=>{for(const source of ['<table><tr><td>Alice</td><td>2</td></tr></table>','<img src="https://example.test/image.png">','原始描述']){const state=fixture();state.records[1].data.description=source;setupApi(state);const host=document.createElement('div');document.body.append(host as any);const root=createRoot(host as any);try{await act(async()=>root.render(<Workspace user={user}/>));await settle();await act(async()=>click(host.querySelector('.task-body')));const mode=host.querySelector('select[aria-label="编辑方式"]') as unknown as HTMLSelectElement;if(source==='原始描述'){await act(async()=>{mode.value='markdown';mode.dispatchEvent(new window.Event('change',{bubbles:true}))})}assert.equal(mode.value,'markdown');const textarea=host.querySelector<HTMLTextAreaElement>('.description-input')!;assert.equal(textarea.value,source);const draft=(source==='原始描述'?'<table><tr><td>未保存的新HTML</td></tr></table>':source)+'\n\n新输入未保存';await act(async()=>type(textarea,draft));await act(async()=>{mode.value='rich';mode.dispatchEvent(new window.Event('change',{bubbles:true}))});assert.equal(host.querySelector('.rich-body'),null);assert.equal(host.querySelector<HTMLTextAreaElement>('.description-input')?.value,draft);await act(async()=>textarea.dispatchEvent(new window.FocusEvent('focusout',{bubbles:true})));await settle();assert.equal(state.records.find(r=>r.id==='task-ui')?.data.description,draft)}finally{await act(async()=>root.unmount());host.remove();window.happyDOM.abort();}}});

test('Undo dispatch follows actual title edit versus wont-do completion action',async()=>{for(const scenario of ['edit','wontdo']){const state=fixture(),calls:any[]=[];if(scenario==='edit'){state.records[1].data.status='done';state.records[1].data.completionMutation='original';}setupApi(state,calls);const host=document.createElement('div');document.body.append(host as any);const root=createRoot(host as any);try{await act(async()=>root.render(<Workspace user={user}/>));await settle();if(scenario==='edit'){const toggle=Array.from(host.querySelectorAll('label')).find(l=>l.textContent?.includes('显示已完成'))?.querySelector('input');await act(async()=>click(toggle||null));}await act(async()=>click(host.querySelector('.task-body')));if(scenario==='edit'){const title=host.querySelector<HTMLInputElement>('[aria-label="任务标题"]')!;await act(async()=>type(title,'编辑后的标题'));await act(async()=>title.dispatchEvent(new window.FocusEvent('focusout',{bubbles:true})));await settle();}else{await act(async()=>click(host.querySelector('button[title="更多操作"]')));await act(async()=>click(Array.from(host.querySelectorAll<HTMLButtonElement>('.detail-panel .context-menu button')).find(b=>b.textContent?.trim()==='暂不处理')||null));await settle();}assert.equal(state.records.find(r=>r.id==='task-ui')?.data.status,scenario==='edit'?'done':'wontdo',JSON.stringify(calls));const before=calls.length;await act(async()=>document.body.dispatchEvent(new window.KeyboardEvent('keydown',{key:'z',ctrlKey:true,bubbles:true})));await settle();const dispatched=calls.slice(before).find(c=>c.operation!=='check');assert.equal(dispatched?.operation,scenario==='edit'?'upsert':'undoComplete',JSON.stringify({scenario,calls,before}));assert.equal(state.records.find(r=>r.id==='task-ui')?.data.status,scenario==='edit'?'done':'open')}finally{await act(async()=>root.unmount());host.remove();window.happyDOM.abort();}}});

test('failed update input survives navigation and shows newer remote conflict without overwriting',async()=>{const state=fixture(),calls:any[]=[];draftStore.removeItem('qingdan:pending-write:'+user.userId);setupApi(state,calls);const original=g.fetch;let fail=true;g.fetch=async(path:string,init?:RequestInit)=>{const b=init?.body?JSON.parse(init.body as string):undefined;if(fail&&b?.operation==='upsert'&&b.id==='task-ui'){fail=false;return Response.json({error:'模拟连接中断'},{status:503})}return original(path,init)};const host=document.createElement('div');document.body.append(host as any);const root=createRoot(host as any);try{await act(async()=>root.render(<Workspace user={user}/>));await settle();await act(async()=>click(host.querySelector('.task-body')));const title=host.querySelector<HTMLInputElement>('[aria-label="任务标题"]')!;await act(async()=>type(title,'离线尚未提交的标题'));await act(async()=>title.dispatchEvent(new window.FocusEvent('focusout',{bubbles:true})));await settle();assert.match(host.querySelector('.write-pending-banner')?.textContent||'',/1 条修改/);assert.ok(Object.keys(localStorage).some(k=>k.startsWith('qingdan:queue:write:'+user.userId+':')&&localStorage.getItem(k)?.includes('离线尚未提交的标题')));await act(async()=>click(host.querySelector('button[aria-label="专注"]')));state.records[1]={...state.records[1],revision:2,data:{...state.records[1].data,title:'另一设备的新标题'}};await act(async()=>click(btn('查看与恢复')));const writesBefore=calls.filter(c=>c.operation==='upsert').length;await act(async()=>click(btn('同步并核对重试')));await settle();assert.match(host.querySelector('.pending-write-card')?.textContent||'',/较新云端冲突/);assert.match(host.querySelector('.pending-write-card')?.textContent||'',/离线尚未提交的标题/);assert.match(host.querySelector('.pending-write-card')?.textContent||'',/另一设备的新标题/);assert.equal(calls.filter(c=>c.operation==='upsert').length,writesBefore);assert.equal(state.records.find(r=>r.id==='task-ui')?.data.title,'另一设备的新标题')}finally{await act(async()=>root.unmount());host.remove();draftStore.removeItem('qingdan:pending-write:'+user.userId);window.happyDOM.abort();}});

test('unknown successful update response reconciles without duplicate save on retry',async()=>{const state=fixture(),calls:any[]=[];draftStore.removeItem('qingdan:pending-write:'+user.userId);setupApi(state,calls);const original=g.fetch;let lose=true;g.fetch=async(path:string,init?:RequestInit)=>{const b=init?.body?JSON.parse(init.body as string):undefined;const response=await original(path,init);if(lose&&b?.operation==='upsert'&&b.id==='task-ui'){lose=false;throw new TypeError('模拟提交后连接断开')}return response};const host=document.createElement('div');document.body.append(host as any);const root=createRoot(host as any);try{await act(async()=>root.render(<Workspace user={user}/>));await settle();await act(async()=>click(host.querySelector('.task-body')));const title=host.querySelector<HTMLInputElement>('[aria-label="任务标题"]')!;await act(async()=>type(title,'已提交但响应未知'));await act(async()=>title.dispatchEvent(new window.FocusEvent('focusout',{bubbles:true})));await settle();assert.equal(state.records.find(r=>r.id==='task-ui')?.data.title,'已提交但响应未知');assert.match(host.querySelector('.write-pending-banner')?.textContent||'',/1 条修改/);await act(async()=>click(btn('查看与恢复')));await act(async()=>click(btn('同步并核对重试')));await settle();assert.equal(calls.filter(c=>c.operation==='upsert'&&c.id==='task-ui').length,1);assert.equal(host.querySelector('.pending-banner'),null);assert.match(host.querySelector('.pending-write-dialog')?.textContent||'',/没有待确认修改/)}finally{await act(async()=>root.unmount());host.remove();draftStore.removeItem('qingdan:pending-write:'+user.userId);window.happyDOM.abort();}});

test('quick-add and unblurred detail/form drafts restore after workspace remount',async()=>{const state=fixture();setupApi(state);draftStore.removeItem('qingdan:quick-draft:'+user.userId);const host=document.createElement('div');document.body.append(host as any);let root=createRoot(host as any);try{await act(async()=>root.render(<Workspace user={user}/>));await settle();await act(async()=>type(host.querySelector<HTMLTextAreaElement>('.quick-add textarea')!,'还没提交的快速任务'));assert.equal(draftStore.getItem('qingdan:quick-draft:'+user.userId),'还没提交的快速任务');await act(async()=>click(host.querySelector('.task-body')));await act(async()=>type(host.querySelector<HTMLInputElement>('[aria-label="任务标题"]')!,'未失焦的标题草稿'));await act(async()=>type(host.querySelector<HTMLInputElement>('[placeholder="添加检查项"]')!,'未提交检查项'));assert.match(draftStore.getItem('qingdan:draft:'+user.userId+':task-ui')||'',/未失焦的标题草稿/);await act(async()=>root.unmount());host.textContent='';root=createRoot(host as any);await act(async()=>root.render(<Workspace user={user}/>));await settle();assert.equal(host.querySelector<HTMLTextAreaElement>('.quick-add textarea')?.value,'还没提交的快速任务');await act(async()=>click(host.querySelector('.task-body')));assert.equal(host.querySelector<HTMLTextAreaElement>('[aria-label="任务标题"]')?.value,'未失焦的标题草稿');assert.equal(host.querySelector<HTMLInputElement>('[placeholder="添加检查项"]')?.value,'未提交检查项')}finally{await act(async()=>root.unmount());host.remove();for(const k of ['qingdan:quick-draft:'+user.userId,'qingdan:check-draft:'+user.userId+':task-ui','qingdan:draft:'+user.userId+':task-ui'])draftStore.removeItem(k);window.happyDOM.abort();}});

test('independent checklist reminder saves an explicit instant without a parent due date',async()=>{const state=fixture();state.records[1].data.dueDate='';state.records.push({id:'settings:'+user.userId,ownerId:user.userId,kind:'settings',listId:null,data:{timezone:'Etc/UTC'},revision:1,updatedAt:new Date().toISOString(),deleted:false,role:'owner'});setupApi(state);const host=document.createElement('div');document.body.append(host as any);const root=createRoot(host as any);try{await act(async()=>root.render(<Workspace user={user}/>));await settle();await act(async()=>click(Array.from(host.querySelectorAll<HTMLButtonElement>('.nav-item')).find(b=>b.textContent?.includes('所有任务'))||null));await act(async()=>click(host.querySelector('.task-body')));const reminder=host.querySelector<HTMLInputElement>('[aria-label="检查项提醒 第一项"]')!;await act(async()=>type(reminder,'2026-10-08T09:15'));await settle();const c=state.records.find(r=>r.id==='task-ui')?.data.checkItems?.[0];assert.equal(c?.reminderAt,'2026-10-08T09:15:00Z');assert.equal(c?.reminderTimeZone,'Etc/UTC');assert.equal(state.records.find(r=>r.id==='task-ui')?.data.dueDate,'')}finally{await act(async()=>root.unmount());host.remove();window.happyDOM.abort();}});

test('collaboration activity has durable per-task unread markers and mark-all',async()=>{const state=fixture();state.records[1].data.comments=[{id:'comment-other',text:'另一成员的评论',author:'Other',authorId:'other-fixture',createdAt:new Date(Date.now()-1000).toISOString()}];setupApi(state);const host=document.createElement('div');document.body.append(host as any);const root=createRoot(host as any);try{await act(async()=>root.render(<Workspace user={user}/>));await settle();assert.equal(host.querySelector('.rail-badge')?.textContent,'1');await act(async()=>click(host.querySelector('button[aria-label="协作动态"]')));assert.match(host.querySelector('.activity-card')?.textContent||'',/另一成员的评论/);await act(async()=>click(host.querySelector('.activity-card')));await settle();assert.ok(state.records.find(r=>r.kind==='settings')?.data.readMarkers?.['task-ui']);assert.equal(host.querySelector('.rail-badge'),null);await act(async()=>click(btn('全部标为已读')));await settle();assert.ok(state.records.find(r=>r.kind==='settings')?.data.activityReadAt)}finally{await act(async()=>root.unmount());host.remove();window.happyDOM.abort();}});

test('large nested list renders bounded rows, loads more and searches all loaded canonical data',async()=>{const state=fixture(),parent=state.records[1];for(let i=0;i<1200;i++)state.records.push({...parent,id:'large-'+i,data:{...parent.data,title:i===1199?'最后一个查找目标':'子任务 '+i,parentId:parent.id,checkItems:[]}});setupApi(state);const host=document.createElement('div');document.body.append(host as any);const root=createRoot(host as any);try{await act(async()=>root.render(<Workspace user={user}/>));await settle();assert.equal(host.querySelectorAll('.task-row').length,200);assert.match(host.querySelector('.render-page-footer')?.textContent||'',/200 \/ 1201/);await act(async()=>click(btn('再显示200行')));assert.equal(host.querySelectorAll('.task-row').length,400);await act(async()=>document.body.dispatchEvent(new window.KeyboardEvent('keydown',{key:'/',bubbles:true})));await settle();await act(async()=>type(host.querySelector<HTMLInputElement>('#search')!,'最后一个查找目标'));assert.equal(host.querySelectorAll('.task-row').length,1);assert.match(host.querySelector('.task-title')?.textContent||'',/最后一个查找目标/)}finally{await act(async()=>root.unmount());host.remove();window.happyDOM.abort();}});

test('switching authenticated account does not expose another account persistent drafts or queue',async()=>{const other={userId:'other-account',displayName:'Other',email:'other@example.test'};draftStore.setItem('qingdan:quick-draft:'+user.userId,'账号A的私有未提交文本');draftStore.setItem('qingdan:draft:'+user.userId+':task-ui',JSON.stringify({title:'账号A的私有标题',description:'',dirty:{title:true}}));const state=fixture();state.user=other;state.records=state.records.map(r=>({...r,ownerId:other.userId,role:'owner'}));g.fetch=async()=>Response.json(state);const host=document.createElement('div');document.body.append(host as any);const root=createRoot(host as any);try{await act(async()=>root.render(<Workspace user={other}/>));await settle();assert.equal(host.querySelector<HTMLTextAreaElement>('.quick-add textarea')?.value,'');await act(async()=>click(host.querySelector('.task-body')));assert.equal(host.querySelector<HTMLTextAreaElement>('[aria-label="任务标题"]')?.value,'明确定义的示例任务');assert.doesNotMatch(host.textContent||'',/账号A的私有/);assert.equal(host.querySelector('.pending-banner'),null)}finally{await act(async()=>root.unmount());host.remove();draftStore.removeItem('qingdan:quick-draft:'+user.userId);draftStore.removeItem('qingdan:draft:'+user.userId+':task-ui');window.happyDOM.abort();}});

