test('multiselect edits priority, add/remove tags and member assignment without replacing unrelated tags',async()=>{const state=fixture(),first=state.records[1];first.data.tags=['保留','移除'];state.records.push({...first,id:'second-bulk',data:{...first.data,title:'第二条批量任务',tags:['不同','移除']}});state.members=[{listId:first.listId!,userId:'member',email:'member@example.test',role:'edit'}];setupApi(state);const host=document.createElement('div');document.body.append(host as any);const root=createRoot(host as any);const selectBoth=async()=>{await act(async()=>{for(const input of host.querySelectorAll<HTMLInputElement>('.batch-check'))if(!input.checked)click(input)});};const change=async(label:string,value:string)=>{const el=host.querySelector('select[aria-label="'+label+'"]')as unknown as HTMLSelectElement;await act(async()=>{el.value=value;el.dispatchEvent(new window.Event('change',{bubbles:true}))});await settle();};try{await act(async()=>root.render(<Workspace user={user}/>));await settle();await selectBoth();await change('批量优先级','3');assert.ok(state.records.filter(r=>r.kind==='task').every(r=>r.data.priority===3));await selectBoth();await act(async()=>type(host.querySelector<HTMLInputElement>('[aria-label="批量标签"]')!,'新标签'));await act(async()=>click(btn('添加标签')));await settle();assert.deepEqual(state.records.find(r=>r.id==='task-ui')?.data.tags,['保留','移除','新标签']);assert.deepEqual(state.records.find(r=>r.id==='second-bulk')?.data.tags,['不同','移除','新标签']);await selectBoth();await act(async()=>type(host.querySelector<HTMLInputElement>('[aria-label="批量标签"]')!,'移除'));await act(async()=>click(btn('移除标签')));await settle();assert.ok(state.records.filter(r=>r.kind==='task').every(r=>!r.data.tags?.includes('移除')));await selectBoth();await change('批量分配','member@example.test');assert.ok(state.records.filter(r=>r.kind==='task').every(r=>r.data.assignee==='member@example.test'));await selectBoth();await change('批量分配','__none__');assert.ok(state.records.filter(r=>r.kind==='task').every(r=>r.data.assignee===''))}finally{await act(async()=>root.unmount());host.remove();window.happyDOM.abort();}});

test('detail trash routes whole real subtree through dedicated service and Undo restores mixed states',async()=>{const{trashPlan,restorePlan}=await import('../lib/trash-plan');const state=fixture(),parent=state.records[1];state.records.push({...parent,id:'trash-child',data:{...parent.data,title:'已完成真实子任务',parentId:parent.id,status:'done',description:'应保留的原文'}});setupApi(state);const original=g.fetch,trashCalls:any[]=[];g.confirm=()=>true;g.fetch=async(path:string,init?:RequestInit)=>{if(path==='/api/task-trash'){const body=JSON.parse(init!.body as string);trashCalls.push(body);assert.equal(body.expectedRevision,state.records.find(r=>r.id===body.id)?.revision,'trash request must carry current fixture revision');const originals=body.deleted?state.records.filter(r=>r.id===body.id||r.data.parentId===body.id):state.records.filter(r=>r.data.trashRoot===body.id);const changed=body.deleted?trashPlan(originals,body.id,'fixture-trash',new Date().toISOString()):restorePlan(originals,body.id,new Date().toISOString());state.records=state.records.map(r=>changed.find(c=>c.id===r.id)||r);return Response.json({records:changed})}return original(path,init)};const host=document.createElement('div');document.body.append(host as any);const root=createRoot(host as any);try{await act(async()=>root.render(<Workspace user={user}/>));await settle();await act(async()=>click(host.querySelector('.task-body')));await act(async()=>click(host.querySelector('button[title="更多操作"]')));await act(async()=>click(Array.from(host.querySelectorAll<HTMLButtonElement>('.detail-panel .context-menu button')).find(b=>b.textContent?.trim()==='移入回收站')||null));await settle();assert.equal(trashCalls.length,1);assert.ok(trashCalls[0].expectedRevision>=1);assert.ok(state.records.filter(r=>r.kind==='task').every(r=>r.deleted));assert.ok(trashCalls[0].clientOperationId);await act(async()=>document.body.dispatchEvent(new window.KeyboardEvent('keydown',{key:'z',ctrlKey:true,bubbles:true})));await settle();assert.equal(trashCalls.length,2);assert.equal(trashCalls[1].deleted,false);assert.ok(state.records.filter(r=>r.kind==='task').every(r=>!r.deleted));assert.equal(state.records.find(r=>r.id==='trash-child')?.data.status,'done');assert.equal(state.records.find(r=>r.id==='trash-child')?.data.description,'应保留的原文')}finally{await act(async()=>root.unmount());host.remove();window.happyDOM.abort();}});

test('explicit source/target merge retains source attachment metadata and Undo restores real child parent',async()=>{const{mergePlan,undoMergePlan}=await import('../lib/merge-plan');const state=fixture(),target=state.records[1],source={...target,id:'merge-source',data:{...target.data,title:'来源任务',description:'来源正文',tags:['来源标签'],checkItems:[{id:'a',title:'来源检查',done:true}]}};const child={...target,id:'merge-child',data:{...target.data,title:'来源已完成子任务',description:'孩子的独立正文',parentId:source.id,status:'done' as const}};state.records.push(source,child);state.attachments=[{id:'source-file',recordId:source.id,name:'保留来源附件.txt',mime:'text/plain',size:10,createdAt:new Date().toISOString()}];setupApi(state);const original=g.fetch,mergeCalls:any[]=[];let before:AppRecord[]=[];g.fetch=async(path:string,init?:RequestInit)=>{if(path==='/api/task-merge'){const b=JSON.parse(init!.body as string);mergeCalls.push(b);const ids=['task-ui','merge-source','merge-child'],records=state.records.filter(r=>ids.includes(r.id));let changed;if(b.operation==='merge'){before=structuredClone(records);assert.equal(b.targetId,'task-ui');assert.equal(b.inputs.length,2);changed=mergePlan(records,b.targetId,['merge-source'],'fixture-merge',new Date().toISOString())}else{assert.equal(b.expectedRevision,state.records.find(r=>r.id===b.targetId)?.revision);changed=undoMergePlan(records,before,b.targetId,new Date().toISOString())}state.records=state.records.map(r=>changed.find(c=>c.id===r.id)||r);return Response.json({records:changed})}return original(path,init)};const host=document.createElement('div');document.body.append(host as any);const root=createRoot(host as any);try{await act(async()=>root.render(<Workspace user={user}/>));await settle();await act(async()=>{for(const box of host.querySelectorAll<HTMLInputElement>('.batch-check'))if(!box.getAttribute('aria-label')?.includes('子任务'))click(box)});await act(async()=>click(btn('合并任务…')));assert.match(document.querySelector('.modal')?.textContent||'',/目标的标题、日期和优先级保留/);assert.equal((btn('确认来源与目标并合并') as HTMLButtonElement)?.disabled,false,document.querySelector('.modal')?.textContent||'');await act(async()=>click(btn('确认来源与目标并合并')));await settle();assert.equal(mergeCalls.length,1);assert.ok(mergeCalls[0].clientOperationId);assert.equal(state.records.find(r=>r.id==='merge-source')?.deleted,true);assert.equal(state.records.find(r=>r.id==='merge-child')?.data.parentId,'task-ui');assert.equal(state.records.find(r=>r.id==='merge-child')?.data.status,'done');assert.match(state.records.find(r=>r.id==='task-ui')?.data.description||'',/来源正文/);assert.match(host.querySelector('.detail-panel')?.textContent||'',/保留来源附件.txt/);await act(async()=>click(host.querySelector('button[title="更多操作"]')));await act(async()=>click(Array.from(host.querySelectorAll<HTMLButtonElement>('.detail-panel .context-menu button')).find(b=>b.textContent?.trim()==='撤销此次合并')||null));await settle();assert.equal(mergeCalls.length,2);assert.equal(state.records.find(r=>r.id==='merge-source')?.deleted,false);assert.equal(state.records.find(r=>r.id==='merge-child')?.data.parentId,'merge-source');assert.equal(state.records.find(r=>r.id==='task-ui')?.data.description,'原始描述');assert.equal(state.attachments[0].recordId,'merge-source')}finally{await act(async()=>root.unmount());host.remove();window.happyDOM.abort();}});

test('unknown committed merge reuses its persisted operation ID and applies canonical child state once',async()=>{const{mergePlan}=await import('../lib/merge-plan');const state=fixture(),target=state.records[1],source={...target,id:'unknown-source',data:{...target.data,title:'未知结果来源',description:'只合入一次的正文'}},child={...target,id:'unknown-child',data:{...target.data,title:'真实子任务',parentId:source.id}};state.records.push(source,child);setupApi(state);const original=g.fetch,requests:any[]=[];let committed=0,receipt:any;g.fetch=async(path:string,init?:RequestInit)=>{if(path==='/api/task-merge'){const b=JSON.parse(init!.body as string);requests.push(b);if(receipt){assert.equal(b.clientOperationId,receipt.id);return Response.json({records:state.records.filter(r=>receipt.ids.includes(r.id)),replayed:true})}const originals=state.records.filter(r=>['task-ui','unknown-source','unknown-child'].includes(r.id));const changed=mergePlan(originals,'task-ui',['unknown-source'],'unknown-fixture-op',new Date().toISOString());state.records=state.records.map(r=>changed.find(c=>c.id===r.id)||r);committed++;receipt={id:b.clientOperationId,ids:changed.map(r=>r.id)};throw new TypeError('模拟合并已提交但响应断开')}return original(path,init)};const host=document.createElement('div');document.body.append(host as any);const root=createRoot(host as any);try{await act(async()=>root.render(<Workspace user={user}/>));await settle();await act(async()=>{for(const box of host.querySelectorAll<HTMLInputElement>('.batch-check'))if(!box.getAttribute('aria-label')?.includes('子任务'))click(box)});await act(async()=>click(btn('合并任务…')));await act(async()=>click(btn('确认来源与目标并合并')));await settle();assert.equal(committed,1);assert.match(host.querySelector('.write-pending-banner')?.textContent||'',/1 条修改/);await act(async()=>click(btn('关闭')));await act(async()=>click(btn('查看与恢复')));assert.match(host.querySelector('.pending-write-card')?.textContent||'',/沿用同一操作标识/);await act(async()=>click(btn('同步并核对重试')));await settle();assert.equal(requests.length,2);assert.equal(committed,1);assert.equal(host.querySelector('.pending-banner'),null);assert.equal(state.records.find(r=>r.id==='unknown-child')?.data.parentId,'task-ui');assert.equal((state.records.find(r=>r.id==='task-ui')?.data.description||'').split('只合入一次的正文').length-1,1)}finally{await act(async()=>root.unmount());host.remove();window.happyDOM.abort();}});

