test('task pomodoro estimate persists and displays full segments without counting partial/break sessions',async()=>{const state=fixture();for(const [id,mode,seconds]of[['full','pomodoro',1500],['partial','pomodoro',600],['break','break',1500]]as const)state.records.push({id,ownerId:user.userId,kind:'focus',listId:null,data:{taskId:'task-ui',mode,seconds,duration:25,focusStatus:'finished'},revision:1,updatedAt:new Date().toISOString(),deleted:false,role:'owner'});setupApi(state);const host=document.createElement('div');document.body.append(host as any);const root=createRoot(host as any);try{await act(async()=>root.render(<Workspace user={user}/>));await settle();await act(async()=>click(host.querySelector('.task-body')));await act(async()=>type(host.querySelector<HTMLInputElement>('[aria-label="预估番茄段数"]')!,'3'));await settle();assert.equal(state.records.find(r=>r.id==='task-ui')?.data.estimatedPomodoros,3);assert.match(host.querySelector('.detail-properties')?.textContent||'',/完整番茄 1 \/ 3 段/);assert.match(host.querySelector('.detail-properties')?.textContent||'',/实际 35 分钟/);assert.match(host.querySelector('.detail-properties')?.textContent||'',/还需 2 段/)}finally{await act(async()=>root.unmount());host.remove();window.happyDOM.abort();}});

