test('countdown page reminder settings persist explicit time, zone and offsets without implying background delivery',async()=>{const state=fixture();state.records.push({id:'reminder-count',ownerId:user.userId,kind:'countdown',listId:null,data:{title:'周年提醒',dueDate:localDate(),countdownType:'anniversary'},revision:1,updatedAt:new Date().toISOString(),deleted:false,role:'owner'});setupApi(state);const host=document.createElement('div');document.body.append(host as any);const root=createRoot(host as any);try{await act(async()=>root.render(<Workspace user={user}/>));await settle();await act(async()=>click(host.querySelector('button[aria-label="倒数日"]')));await act(async()=>click(host.querySelector('button[title="编辑倒数日"]')));const select=host.querySelector('select[aria-label="倒数日提醒"]')as unknown as HTMLSelectElement;await act(async()=>{select.value='1440,0';select.dispatchEvent(new window.Event('change',{bubbles:true}))});await act(async()=>type(host.querySelector<HTMLInputElement>('[aria-label="倒数日提醒时间"]')!,'09:30'));await act(async()=>type(host.querySelector<HTMLInputElement>('[aria-label="倒数日提醒时区"]')!,'Etc/UTC'));assert.match(document.querySelector('.modal')?.textContent||'',/关闭页面没有推送或邮件保证/);await act(async()=>click(btn('保存')));await settle();const saved=state.records.find(r=>r.id==='reminder-count')!.data;assert.deepEqual(saved.reminders,[1440,0]);assert.equal(saved.dueTime,'09:30');assert.equal(saved.timezone,'Etc/UTC')}finally{await act(async()=>root.unmount());host.remove();window.happyDOM.abort();}});

test('real rich schema renders and edits table cells while retaining image link metadata without automatic requests',async()=>{const{default:RichEditor}=await import('../app/rich-editor');const{richMarkdownManager}=await import('../lib/rich-schema');const value='Name | Count\n--- | ---\nAlice | 2\n\n![Photo](<https://example.test/a_(b).png> "A title")';const host=document.createElement('div');document.body.append(host as any);const root=createRoot(host as any);let saved=value;const originalPrompt=g.prompt;try{await act(async()=>root.render(<RichEditor value={value} editable version={1} dirty={false} onChange={text=>{saved=text}} onBlur={()=>{}}/>));await settle();assert.match(host.querySelector('table')?.textContent||'',/Alice/);assert.match(host.querySelector('.rich-linked-image')?.textContent||'',/https:\/\/example.test\/a_\(b\).png/);assert.equal(!!host.querySelector('img[src]'),false);const editor=(host.querySelector('.rich-body')as any).editor;let cellPosition=-1;editor.state.doc.descendants((node:any,pos:number)=>{if(node.isText&&node.text==='2')cellPosition=pos});assert.ok(cellPosition>=0);await act(async()=>{editor.commands.setTextSelection({from:cellPosition,to:cellPosition+1});editor.commands.insertContent('3')});assert.match(host.querySelector('table')?.textContent||'',/Alice3/);const responses=['https://example.test/new_(image).png','Changed [alt]','Changed "title"'];g.prompt=()=>responses.shift()||'';await act(async()=>click(Array.from(host.querySelectorAll<HTMLButtonElement>('button')).find(b=>b.textContent==='编辑图片链接')||null));await settle();const serialized=richMarkdownManager().parse(saved);assert.match(saved,/Alice/);assert.match(saved,/Count/);assert.match(JSON.stringify(serialized),/new_\(image\)\.png/);assert.match(JSON.stringify(serialized),/Changed \[alt\]/);assert.match(JSON.stringify(serialized),/Changed \\"title\\"/);assert.equal(!!host.querySelector('img[src]'),false)}finally{g.prompt=originalPrompt;await act(async()=>root.unmount());host.remove();window.happyDOM.abort();}});

test('unsaved Markdown table/image draft switches to rich editor without dropping cells or URLs',async()=>{const state=fixture();setupApi(state);const host=document.createElement('div');document.body.append(host as any);const root=createRoot(host as any);try{await act(async()=>root.render(<Workspace user={user}/>));await settle();await act(async()=>click(host.querySelector('.task-body')));const mode=host.querySelector('select[aria-label="编辑方式"]')as unknown as HTMLSelectElement;await act(async()=>{mode.value='markdown';mode.dispatchEvent(new window.Event('change',{bubbles:true}))});const draft='Name | Count\n--- | ---\nAlice | 2\n\n![Photo](https://example.test/preserved.png)';await act(async()=>type(host.querySelector<HTMLTextAreaElement>('.description-input')!,draft));await act(async()=>{mode.value='rich';mode.dispatchEvent(new window.Event('change',{bubbles:true}))});await settle();assert.match(host.querySelector('table')?.textContent||'',/Alice2/);assert.match(host.querySelector('.rich-linked-image')?.textContent||'',/preserved\.png/);assert.equal(!!host.querySelector('.rich-body img[src]'),false);assert.ok(draftStore.getItem('qingdan:draft:'+user.userId+':task-ui')?.includes('preserved.png'))}finally{await act(async()=>root.unmount());host.remove();draftStore.removeItem('qingdan:draft:'+user.userId+':task-ui');window.happyDOM.abort();}});


