test('forbidden response cannot revive an old cached workspace or private task text',async()=>{const{WorkspaceCache,browserCacheBackend}=await import('../lib/workspace-cache');const state=fixture();state.records[1].data.title='不应从缓存绕过拒绝的文字';const cache=new WorkspaceCache(user.userId,browserCacheBackend());await cache.save(state);g.fetch=async()=>Response.json({error:'当前访问已拒绝'},{status:403});const host=document.createElement('div');document.body.append(host as any);const root=createRoot(host as any);try{await act(async()=>root.render(<Workspace user={user}/>));await settle();assert.match(host.textContent||'',/当前会话需重新验证/);assert.equal(host.querySelectorAll('.task-row').length,0);assert.doesNotMatch(host.textContent||'',/不应从缓存绕过拒绝的文字/);assert.equal(await cache.load(),null)}finally{await act(async()=>root.unmount());host.remove();window.happyDOM.abort();}});

test('lost habit increment response survives remount and retries the persisted intent once',async()=>{const state=fixture();state.records.push({...state.records[1],id:'habit-ui',kind:'habit',listId:null,data:{title:'模拟喝水习惯',unit:'杯',target:8,weekdays:[0,1,2,3,4,5,6]}});setupApi(state);const original=g.fetch,requests:any[]=[];let commits=0,operation='';g.fetch=async(path:string,init?:RequestInit)=>{const body=init?.body?JSON.parse(init.body as string):undefined;if(body?.operation==='habitIncrement'){requests.push(body);if(operation){assert.equal(body.clientOperationId,operation);return Response.json({record:state.records.find(r=>r.id==='habitlog:habit-ui:'+body.date),replayed:true})}operation=body.clientOperationId;commits++;state.records.push({...state.records[1],id:'habitlog:habit-ui:'+body.date,kind:'habitLog',listId:null,data:{habitId:'habit-ui',date:body.date,value:1,note:''}});throw new TypeError('提交成功后模拟断网')}return original(path,init)};const host=document.createElement('div');document.body.append(host as any);let root=createRoot(host as any);try{await act(async()=>root.render(<Workspace user={user}/>));await settle();await act(async()=>click(host.querySelector('button[aria-label="习惯"]')));await act(async()=>click(Array.from(host.querySelectorAll<HTMLButtonElement>('.habit-count button')).find(b=>b.textContent==='+')||null));await settle();assert.ok(host.querySelector('.write-pending-banner'));await act(async()=>root.unmount());root=createRoot(host as any);await act(async()=>root.render(<Workspace user={user}/>));await settle();await act(async()=>click(btn('查看与恢复')));await act(async()=>click(btn('同步并核对重试')));await settle();assert.equal(commits,1);assert.equal(requests.length,2);assert.equal(!!host.querySelector('.write-pending-banner'),false);assert.equal(state.records.find(r=>r.kind==='habitLog')?.data.value,1)}finally{await act(async()=>root.unmount());host.remove();window.happyDOM.abort();}});

test('lost comment response retries one append and preserves a newer typed comment draft',async()=>{const state=fixture();setupApi(state);draftStore.removeItem('qingdan:comment-draft:'+user.userId+':task-ui');const original=g.fetch,requests:any[]=[];let commits=0,operation='';g.fetch=async(path:string,init?:RequestInit)=>{const body=init?.body?JSON.parse(init.body as string):undefined;if(body?.operation==='comment'){requests.push(body);if(operation){assert.equal(body.clientOperationId,operation);return Response.json({record:state.records.find(r=>r.id===body.id),replayed:true})}operation=body.clientOperationId;commits++;state.records=state.records.map(r=>r.id===body.id?{...r,revision:r.revision+1,data:{...r.data,comments:[{id:'comment-fixture',author:user.displayName,authorId:user.userId,text:body.text,createdAt:new Date().toISOString()}]}}:r);throw new TypeError('评论已提交，响应模拟丢失')}return original(path,init)};const host=document.createElement('div');document.body.append(host as any);const root=createRoot(host as any);try{await act(async()=>root.render(<Workspace user={user}/>));await settle();await act(async()=>click(host.querySelector('.task-body')));await act(async()=>click(Array.from(host.querySelectorAll<HTMLButtonElement>('.detail-tabs button')).find(b=>b.textContent==='评论')||null));await act(async()=>type(host.querySelector<HTMLTextAreaElement>('.comment-form textarea')!,'第一条评论'));await act(async()=>click(btn('发送评论')));await settle();assert.ok(host.querySelector('.write-pending-banner'));await act(async()=>type(host.querySelector<HTMLTextAreaElement>('.comment-form textarea')!,'更新的评论草稿'));await act(async()=>click(btn('查看与恢复')));await act(async()=>click(btn('同步并核对重试')));await settle();assert.equal(commits,1);assert.equal(requests.length,2);assert.equal(state.records.find(r=>r.id==='task-ui')?.data.comments?.length,1);assert.equal(host.querySelector<HTMLTextAreaElement>('.comment-form textarea')?.value,'更新的评论草稿');assert.equal(!!host.querySelector('.write-pending-banner'),false)}finally{await act(async()=>root.unmount());host.remove();draftStore.removeItem('qingdan:comment-draft:'+user.userId+':task-ui');window.happyDOM.abort();}});

test('unknown completion and reopen outcomes use their original operation IDs after fresh sync',async()=>{for(const operation of ['complete','undoComplete']){const state=fixture();if(operation==='undoComplete'){state.records[1].data.status='done';state.records[1].data.completionMutation='fixture-completion'}setupApi(state);const original=g.fetch,requests:any[]=[];let commits=0,id='';g.fetch=async(path:string,init?:RequestInit)=>{const body=init?.body?JSON.parse(init.body as string):undefined;if(body?.operation===operation){requests.push(body);if(id){assert.equal(body.clientOperationId,id);return Response.json({records:[state.records.find(r=>r.id===body.id)],replayed:true})}id=body.clientOperationId;commits++;await original(path,init);throw new TypeError('模拟状态已提交后响应丢失')}return original(path,init)};const host=document.createElement('div');document.body.append(host as any);const root=createRoot(host as any);try{await act(async()=>root.render(<Workspace user={user}/>));await settle();if(operation==='undoComplete'){const toggle=Array.from(host.querySelectorAll('label')).find(l=>l.textContent?.includes('显示已完成'))?.querySelector('input');if(!toggle?.checked)await act(async()=>click(toggle||null))}await act(async()=>click(host.querySelector('.complete-check')));await settle();assert.ok(host.querySelector('.write-pending-banner'));await act(async()=>click(btn('查看与恢复')));await act(async()=>click(btn('同步并核对重试')));await settle();assert.equal(commits,1);assert.equal(requests.length,2);assert.equal(state.records.find(r=>r.id==='task-ui')?.data.status,operation==='complete'?'done':'open');assert.equal(!!host.querySelector('.write-pending-banner'),false)}finally{await act(async()=>root.unmount());host.remove();window.happyDOM.abort();}}});

test('unknown skipped repeat outcome persists across remount and creates only one mocked next instance',async()=>{const state=fixture();state.records[1].data.recurrence={start:{date:localDate()},rule:{frequency:'daily'}};setupApi(state);const original=g.fetch,requests:any[]=[];let commits=0,id='';g.fetch=async(path:string,init?:RequestInit)=>{const body=init?.body?JSON.parse(init.body as string):undefined;if(body?.operation==='skip'){requests.push(body);if(id){assert.equal(body.clientOperationId,id);return Response.json({records:state.records.filter(r=>['task-ui','skip-next-ui'].includes(r.id)),next:'skip-next-ui',replayed:true})}id=body.clientOperationId;commits++;const originalRecord=state.records.find(r=>r.id===body.id)!;state.records=state.records.map(r=>r.id===body.id?{...r,revision:r.revision+1,data:{...r.data,status:'wontdo',completionMutation:'fixture-skip'}}:r);state.records.push({...originalRecord,id:'skip-next-ui',data:{...originalRecord.data,title:'模拟下一次重复',recurrenceSource:originalRecord.id}});throw new TypeError('模拟跳过已提交，返回断开')}return original(path,init)};const host=document.createElement('div');document.body.append(host as any);let root=createRoot(host as any);try{await act(async()=>root.render(<Workspace user={user}/>));await settle();await act(async()=>click(host.querySelector('.task-body')));await act(async()=>click(host.querySelector('button[title="更多操作"]')));await act(async()=>click(Array.from(host.querySelectorAll<HTMLButtonElement>('.detail-panel .context-menu button')).find(b=>b.textContent?.trim()==='跳过这次重复')||null));await settle();assert.ok(host.querySelector('.write-pending-banner'));await act(async()=>root.unmount());root=createRoot(host as any);await act(async()=>root.render(<Workspace user={user}/>));await settle();await act(async()=>click(btn('查看与恢复')));assert.match(document.querySelector('.pending-write-card')?.textContent||'',/跳过重复实例/);await act(async()=>click(btn('同步并核对重试')));await settle();assert.equal(commits,1);assert.equal(requests.length,2);assert.equal(state.records.filter(r=>r.id==='skip-next-ui').length,1);assert.equal(!!host.querySelector('.write-pending-banner'),false)}finally{await act(async()=>root.unmount());host.remove();window.happyDOM.abort();}});

test('confirmed comment retry clears only its matching stored draft while the detail panel is unmounted',async()=>{const state=fixture();setupApi(state);const key='qingdan:comment-draft:'+user.userId+':task-ui';draftStore.removeItem(key);const original=g.fetch;let receipt='';g.fetch=async(path:string,init?:RequestInit)=>{const b=init?.body?JSON.parse(init.body as string):undefined;if(b?.operation==='comment'){if(receipt){assert.equal(b.clientOperationId,receipt);return Response.json({record:state.records.find(r=>r.id===b.id),replayed:true})}receipt=b.clientOperationId;state.records=state.records.map(r=>r.id===b.id?{...r,revision:r.revision+1,data:{...r.data,comments:[{id:'single',author:user.displayName,text:b.text,createdAt:new Date().toISOString()}]}}:r);throw new TypeError('模拟已追加但响应未知')}return original(path,init)};const host=document.createElement('div');document.body.append(host as any);const root=createRoot(host as any);try{await act(async()=>root.render(<Workspace user={user}/>));await settle();await act(async()=>click(host.querySelector('.task-body')));await act(async()=>click(Array.from(host.querySelectorAll<HTMLButtonElement>('.detail-tabs button')).find(b=>b.textContent==='评论')||null));await act(async()=>type(host.querySelector<HTMLTextAreaElement>('.comment-form textarea')!,'待核对评论'));await act(async()=>click(btn('发送评论')));await settle();assert.equal(draftStore.getItem(key),'待核对评论');await act(async()=>click(host.querySelector('button[aria-label="专注"]')));assert.equal(!!host.querySelector('.comment-form'),false);await act(async()=>click(btn('查看与恢复')));await act(async()=>click(btn('同步并核对重试')));await settle();assert.equal(draftStore.getItem(key),null);assert.equal(state.records.find(r=>r.id==='task-ui')?.data.comments?.length,1)}finally{await act(async()=>root.unmount());host.remove();draftStore.removeItem(key);window.happyDOM.abort();}});

