test('unknown habit create locks its immutable submitted payload, reconciles it and retains newer input without a second habit',async()=>{const state=fixture();setupApi(state);const{formDraftKey}=await import('../lib/form-drafts');const key=formDraftKey(user.userId,'habit','new');draftStore.removeItem(key);const original=g.fetch;let committed=false,blockRead=false,lose=true;g.fetch=async(path:string,init?:RequestInit)=>{const b=init?.body?JSON.parse(init.body as string):undefined;if(path==='/api/data'&&!b&&blockRead)throw new TypeError('模拟确认读取也离线');const response=await original(path,init);if(lose&&b?.operation==='upsert'&&b.kind==='habit'){lose=false;committed=true;blockRead=true;throw new TypeError('模拟建立后响应未知')}return response};const host=document.createElement('div');document.body.append(host as any);const root=createRoot(host as any);try{await act(async()=>root.render(<Workspace user={user}/>));await settle();await act(async()=>click(host.querySelector('button[aria-label="习惯"]')));await act(async()=>click(btn('新建习惯')));await act(async()=>type(host.querySelector<HTMLInputElement>('[aria-label="习惯名称"]')!,'Original submitted habit'));await act(async()=>click(btn('保存')));await settle();assert.equal(committed,true);assert.ok(btn('核对并重试原提交'));await act(async()=>type(host.querySelector<HTMLInputElement>('[aria-label="习惯名称"]')!,'Newer habit draft'));assert.equal(btn('保存')?.disabled,true);const pending=JSON.parse(draftStore.getItem(key)!);assert.equal(pending.submission.payload.title,'Original submitted habit');assert.equal(pending.fields.title,'Newer habit draft');blockRead=false;await act(async()=>click(btn('核对并重试原提交')));await settle();assert.equal(host.querySelector<HTMLInputElement>('[aria-label="习惯名称"]')?.value,'Newer habit draft');assert.equal(btn('保存')?.disabled,false);await act(async()=>click(btn('保存')));await settle();assert.equal(state.records.filter(r=>r.kind==='habit').length,1);assert.equal(state.records.find(r=>r.kind==='habit')?.data.title,'Newer habit draft');assert.equal(draftStore.getItem(key),null)}finally{await act(async()=>root.unmount());host.remove();draftStore.removeItem(key);window.happyDOM.abort();}});

test('definite habit validation refusal unlocks correction without losing newer input or leaving a stale create',async()=>{for(const status of[400,422]){const state=fixture();setupApi(state);const{formDraftKey}=await import('../lib/form-drafts');const key=formDraftKey(user.userId,'habit','new');draftStore.removeItem(key);const original=g.fetch;let deliver=()=>{},refuse=true,held=false;g.fetch=async(path:string,init?:RequestInit)=>{const b=init?.body?JSON.parse(init.body as string):undefined;if(refuse&&b?.operation==='upsert'&&b.kind==='habit'){refuse=false;held=true;await new Promise<void>(resolve=>{deliver=resolve});return Response.json({error:'明确校验拒绝，请修正输入'},{status})}return original(path,init)};const host=document.createElement('div');document.body.append(host as any);const root=createRoot(host as any);try{await act(async()=>root.render(<Workspace user={user}/>));await settle();await act(async()=>click(host.querySelector('button[aria-label="习惯"]')));await act(async()=>click(btn('新建习惯')));const name=host.querySelector<HTMLInputElement>('[aria-label="习惯名称"]')!;await act(async()=>type(name,'Alpha refused'));await act(async()=>click(btn('保存')));await settle();assert.equal(held,true);await act(async()=>type(name,'Beta corrected'));await act(async()=>deliver());await settle();assert.equal(host.querySelector<HTMLInputElement>('[aria-label="习惯名称"]')?.value,'Beta corrected');assert.equal(btn('保存')?.disabled,false);assert.equal(btn('核对并重试原提交'),null);assert.equal(JSON.parse(draftStore.getItem(key)!).submission,undefined);assert.equal(state.records.filter(r=>r.kind==='habit').length,0);await act(async()=>click(btn('保存')));await settle();assert.equal(state.records.filter(r=>r.kind==='habit').length,1);assert.equal(state.records.find(r=>r.kind==='habit')?.data.title,'Beta corrected');assert.equal(draftStore.getItem(key),null)}finally{deliver();await act(async()=>root.unmount());host.remove();draftStore.removeItem(key);window.happyDOM.abort();}}});

test('habit original-base conflict retains Alpha and explicit cloud rebase preserves Alpha with newer untouched units',async()=>{const state=fixture();state.records.push({...state.records[1],id:'habit-conflict',kind:'habit',listId:null,data:{title:'Original habit',target:8,unit:'杯',weekdays:[0,1,2,3,4,5,6]}});setupApi(state);const{formDraftKey}=await import('../lib/form-drafts');const key=formDraftKey(user.userId,'habit','habit-conflict');draftStore.removeItem(key);const originalConfirm=g.confirm;g.confirm=()=>true;const host=document.createElement('div');document.body.append(host as any);const root=createRoot(host as any);try{await act(async()=>root.render(<Workspace user={user}/>));await settle();await act(async()=>click(host.querySelector('button[aria-label="习惯"]')));await act(async()=>click(host.querySelector('button[title="编辑习惯"]')));await act(async()=>type(host.querySelector<HTMLInputElement>('[aria-label="习惯名称"]')!,'Alpha local'));state.records=state.records.map(r=>r.id==='habit-conflict'?{...r,revision:2,data:{...r.data,title:'Gamma remote',target:500,unit:'ml'}}:r);await act(async()=>click(btn('保存')));await settle();assert.equal(state.records.find(r=>r.id==='habit-conflict')?.data.title,'Gamma remote');assert.equal(btn('保存')?.disabled,true);assert.ok(draftStore.getItem(key)?.includes('Alpha local'));await act(async()=>click(btn('核对并重试原提交')));await settle();assert.match(host.querySelector('.record-form-draft details')?.textContent||'',/Gamma remote/);await act(async()=>click(btn('明确采用此云端基准')));assert.equal(host.querySelector<HTMLInputElement>('[aria-label="习惯名称"]')?.value,'Alpha local');assert.equal(btn('保存')?.disabled,false);await act(async()=>click(btn('保存')));await settle();const record=state.records.find(r=>r.id==='habit-conflict')!;assert.equal(record.data.title,'Alpha local');assert.equal(record.data.unit,'ml');assert.equal(record.data.target,500);assert.equal(state.records.filter(r=>r.kind==='habit').length,1);assert.equal(draftStore.getItem(key),null)}finally{g.confirm=originalConfirm;await act(async()=>root.unmount());host.remove();draftStore.removeItem(key);window.happyDOM.abort();}});

test('malformed habit weekday draft preserves raw source and disables field editing without crashing the workspace',async()=>{const state=fixture();setupApi(state);const{formDraftKey}=await import('../lib/form-drafts');const key=formDraftKey(user.userId,'habit','new');const raw=JSON.stringify({version:1,accountId:user.userId,kind:'habit',scope:'new',token:'fixture-corrupt',base:null,fields:{title:'Retain raw draft',weekdays:{wrong:true}}});draftStore.setItem(key,raw);const host=document.createElement('div');document.body.append(host as any);const root=createRoot(host as any);try{await act(async()=>root.render(<Workspace user={user}/>));await settle();await act(async()=>click(host.querySelector('button[aria-label="习惯"]')));await act(async()=>click(btn('新建习惯')));await settle();assert.match(host.querySelector('.record-form-draft')?.textContent||'',/执行日格式无效/);assert.equal(host.querySelector<HTMLFieldSetElement>('.record-form-fields')?.disabled,true);assert.equal(btn('保存')?.disabled,true);assert.ok(btn('导出表单草稿'));assert.equal(draftStore.getItem(key),raw);assert.equal(state.records.some(r=>r.kind==='habit'),false)}finally{await act(async()=>root.unmount());host.remove();draftStore.removeItem(key);window.happyDOM.abort();}});

test('whole countdown draft restores date, repeat, reminder, background and unblurred note across navigation',async()=>{const state=fixture();setupApi(state);const{formDraftKey}=await import('../lib/form-drafts');const key=formDraftKey(user.userId,'countdown','new');draftStore.removeItem(key);const host=document.createElement('div');document.body.append(host as any);const root=createRoot(host as any);try{await act(async()=>root.render(<Workspace user={user}/>));await settle();await act(async()=>click(host.querySelector('button[aria-label="倒数日"]')));await act(async()=>click(btn('新建倒数日')));await act(async()=>type(host.querySelector<HTMLInputElement>('[aria-label="倒数日名称"]')!,'保全验收倒数日'));await act(async()=>type(host.querySelector<HTMLInputElement>('[aria-label="倒数日日期"]')!,'2026-11-08'));await act(async()=>type(host.querySelector<HTMLTextAreaElement>('[aria-label="倒数日备注"]')!,'未失焦的完整备注'));await act(async()=>type(host.querySelector<HTMLInputElement>('[aria-label="倒数日分组"]')!,'旅行'));await act(async()=>click(host.querySelector('[aria-label="倒数日重复"]')));await act(async()=>click(host.querySelector('[aria-label="倒数日包含当天"]')));for(const[label,value]of[['倒数日提醒','1440,0'],['倒数日背景','forest'],['倒数日单位','weeks']]){const select=host.querySelector('[aria-label="'+label+'"]')as unknown as HTMLSelectElement;await act(async()=>{select.value=value;select.dispatchEvent(new window.Event('change',{bubbles:true}))})}await act(async()=>click(host.querySelector('[aria-label="关闭倒数日表单并保留草稿"]')));await act(async()=>click(host.querySelector('button[aria-label="专注"]')));await act(async()=>click(host.querySelector('button[aria-label="倒数日"]')));await act(async()=>click(btn('新建倒数日')));assert.equal(host.querySelector<HTMLTextAreaElement>('[aria-label="倒数日备注"]')?.value,'未失焦的完整备注');assert.equal(host.querySelector<HTMLInputElement>('[aria-label="倒数日日期"]')?.value,'2026-11-08');assert.equal(host.querySelector<HTMLInputElement>('[aria-label="倒数日重复"]')?.checked,true);assert.equal((host.querySelector('[aria-label="倒数日背景"]')as unknown as HTMLSelectElement).value,'forest');await act(async()=>click(btn('保存')));await settle();const record=state.records.find(r=>r.kind==='countdown')!;assert.equal(record.data.countdownGroup,'旅行');assert.equal(record.data.recurrence.rule.frequency,'yearly');assert.deepEqual(record.data.reminders,[1440,0]);assert.equal(record.data.countdownUnit,'weeks');assert.equal(record.data.includeStart,true);assert.equal('repeat'in record.data,false);assert.equal(draftStore.getItem(key),null)}finally{await act(async()=>root.unmount());host.remove();draftStore.removeItem(key);window.happyDOM.abort();}});

