test('background upload lost response retains chosen metadata and metadata check avoids reupload',async()=>{const{default:Background}=await import('../app/countdown-background');const{backgroundPendingKey,backgroundIdentity}=await import('../lib/countdown-background');const bytes=new Uint8Array([137,80,78,71,13,10,26,10,1]),id=await backgroundIdentity(bytes,user.userId,'event'),key=backgroundPendingKey(user.userId,'event');draftStore.removeItem(key);const original=g.fetch;let uploads=0,selected='';g.fetch=async(path:string,init?:RequestInit)=>{if(init?.body instanceof FormData){uploads++;throw new TypeError('Lost upload response')}return Response.json({attachment:{id,recordId:'event'}})};const host=document.createElement('div');document.body.append(host as any);const root=createRoot(host as any);try{await act(async()=>root.render(<Background userId={user.userId} recordId="event" selected="" attachments={[]} onSelect={value=>{selected=value}} onRefresh={async()=>{}}/>));const input=host.querySelector<HTMLInputElement>('[aria-label="主动选择倒数日背景文件"]')!;Object.defineProperty(input,'files',{configurable:true,value:[new File([bytes],'Chosen.png',{type:'image/png'})]});await act(async()=>input.dispatchEvent(new window.Event('change',{bubbles:true})));await settle();assert.equal(uploads,1);assert.equal(JSON.parse(draftStore.getItem(key)!).id,id);await act(async()=>click(btn('核对原背景上传')));await settle();assert.equal(selected,id);assert.equal(uploads,1);assert.equal(draftStore.getItem(key),null)}finally{g.fetch=original;await act(async()=>root.unmount());host.remove();draftStore.removeItem(key);window.happyDOM.abort();}});

test('v2 complete backup export retrieves server-owned full package rather than bootstrap summaries',async()=>{const{default:Panel}=await import('../app/full-backup-panel');const{encodeBackupBytes,backupDigest}=await import('../lib/full-backup');const state=fixture(),bytes=new TextEncoder().encode('Fixture attachment');const archive:any={format:'qingdan',version:2,sourceOwner:user.userId,createdAt:new Date().toISOString(),records:state.records,history:[{id:'h',recordId:'task-ui',actorId:user.userId,action:'edit',operationId:'op',createdAt:new Date().toISOString(),snapshot:state.records[1]}],attachments:[{id:'file',recordId:'task-ui',name:'Fixture.txt',mime:'text/plain',size:bytes.length,createdAt:new Date().toISOString(),content:encodeBackupBytes(bytes),sha256:await backupDigest(bytes)}]};const original=g.fetch,oldCreate=URL.createObjectURL;let downloaded:Blob|null=null;g.fetch=async(path:string)=>{assert.equal(path,'/api/backup');return Response.json(archive)};URL.createObjectURL=(blob:Blob)=>{downloaded=blob;return'blob:fixture'};const host=document.createElement('div');document.body.append(host as any);const root=createRoot(host as any);try{await act(async()=>root.render(<Panel userId={user.userId} onRefresh={async()=>{}}/>));await act(async()=>click(btn('导出附件与历史完整包')));await settle();assert.ok(downloaded);const saved=JSON.parse(await(downloaded as unknown as Blob).text());assert.equal(saved.history[0].snapshot.data.title,state.records[1].data.title);assert.equal(saved.attachments[0].content,encodeBackupBytes(bytes));assert.match(host.textContent||'',/2记录 \/ 1历史 \/ 1附件/)}finally{g.fetch=original;URL.createObjectURL=oldCreate;await act(async()=>root.unmount());host.remove();window.happyDOM.abort();}});

test('unknown v2 restore keeps file marker across reopening and exact-content retry confirms one copy',async()=>{const{default:Panel}=await import('../app/full-backup-panel');const{operationHash}=await import('../lib/operations');const archive={format:'qingdan',version:2,sourceOwner:user.userId,createdAt:'2026-10-07T10:00:00Z',records:fixture().records,history:[],attachments:[]},text=JSON.stringify(archive),key='qingdan:full-backup-pending:'+encodeURIComponent(user.userId);draftStore.removeItem(key);const original=g.fetch,oldConfirm=g.confirm;g.confirm=()=>true;const receipts=new Set<string>();let commits=0;g.fetch=async(path:string,init?:RequestInit)=>{assert.equal(path,'/api/backup');const value=JSON.parse(init!.body as string),hash=await operationHash(value);if(!receipts.has(hash)){receipts.add(hash);commits++;throw new TypeError('Lost committed restore response')}return Response.json({count:2,historyCount:0,attachmentCount:0,notices:[],replayed:true})};const host=document.createElement('div');document.body.append(host as any);let root=createRoot(host as any);const render=()=>root.render(<Panel userId={user.userId} onRefresh={async()=>{}}/>);const choose=async()=>{const input=host.querySelector<HTMLInputElement>('[aria-label="主动选择v2完整备份文件"]')!;Object.defineProperty(input,'files',{configurable:true,value:[new File([text],'Fixture.qingdan-v2.json',{type:'application/json'})]});await act(async()=>input.dispatchEvent(new window.Event('change',{bubbles:true})));await settle()};try{await act(async()=>render());await choose();assert.equal(commits,1);assert.match(draftStore.getItem(key)||'',/Fixture.qingdan-v2.json/);await act(async()=>root.unmount());root=createRoot(host as any);await act(async()=>render());assert.match(host.textContent||'',/未确认导入：Fixture.qingdan-v2.json/);await choose();assert.equal(commits,1);assert.equal(draftStore.getItem(key),null);assert.match(host.textContent||'',/原导入已核对，未再次建立副本/)}finally{g.fetch=original;g.confirm=oldConfirm;await act(async()=>root.unmount());host.remove();draftStore.removeItem(key);window.happyDOM.abort();}});

test('ownership transfer requires explicit selected existing member confirmation and cancellation does not submit',async()=>{const{default:Transfer}=await import('../app/list-transfer');const state=fixture(),list={...state.records[0],id:'transfer-list',data:{title:'Shared'}};state.members=[{listId:list.id,userId:'target',email:'target@example.test',role:'read',joinedAt:'2026-10-01T00:00:00Z'}];const key='qingdan:list-transfer:'+encodeURIComponent(user.userId)+':'+list.id;draftStore.removeItem(key);const original=g.fetch,oldConfirm=g.confirm;let questions:string[]=[],calls=0;g.confirm=(message:string)=>{questions.push(message);return false};g.fetch=async()=>{calls++;throw new Error('Unexpected call')};const host=document.createElement('div');document.body.append(host as any);const root=createRoot(host as any);try{await act(async()=>root.render(<Transfer list={list} state={state} onRefresh={async()=>{}}/>));assert.equal(btn('确认转移给所选成员')?.disabled,true);const select=host.querySelector('[aria-label="主动选择清单新所有者"]')as unknown as HTMLSelectElement;await act(async()=>{select.value='target';select.dispatchEvent(new window.Event('change',{bubbles:true}))});await act(async()=>click(btn('确认转移给所选成员')));await settle();assert.equal(calls,0);assert.match(questions[0],/target@example.test/);assert.match(questions[0],/你保留编辑权限/);assert.equal(draftStore.getItem(key),null)}finally{g.fetch=original;g.confirm=oldConfirm;await act(async()=>root.unmount());host.remove();draftStore.removeItem(key);window.happyDOM.abort();}});

test('unknown ownership transfer restores original target membership and operation after owner has changed',async()=>{const{default:Transfer}=await import('../app/list-transfer');const state=fixture();let list:AppRecord={...state.records[0],id:'transfer-list',data:{title:'Shared'}};state.members=[{listId:list.id,userId:'target',email:'target@example.test',role:'read',joinedAt:'2026-10-01T00:00:00Z'}];const key='qingdan:list-transfer:'+encodeURIComponent(user.userId)+':'+list.id;draftStore.removeItem(key);const original=g.fetch,oldConfirm=g.confirm;g.confirm=()=>true;const requests:any[]=[];g.fetch=async(path:string,init?:RequestInit)=>{assert.equal(path,'/api/list-transfer');const body=JSON.parse(init!.body as string);requests.push(body);if(requests.length===1){list={...list,ownerId:'target',revision:2,role:'edit'};throw new TypeError('Lost successful transfer response')}assert.equal(body.clientOperationId,requests[0].clientOperationId);return Response.json({listId:list.id,targetUserId:'target',taskCount:2,replayed:true})};const host=document.createElement('div');document.body.append(host as any);let root=createRoot(host as any);const render=()=>root.render(<Transfer list={list} state={state} onRefresh={async()=>{}}/>);try{await act(async()=>render());const select=host.querySelector('[aria-label="主动选择清单新所有者"]')as unknown as HTMLSelectElement;await act(async()=>{select.value='target';select.dispatchEvent(new window.Event('change',{bubbles:true}))});await act(async()=>click(btn('确认转移给所选成员')));await settle();assert.equal(JSON.parse(draftStore.getItem(key)!).expectedRevision,1);await act(async()=>root.unmount());root=createRoot(host as any);await act(async()=>render());await act(async()=>click(btn('按原操作核对转移结果')));await settle();assert.equal(requests.length,2);assert.equal(requests[1].expectedRevision,1);assert.equal(requests[1].targetJoinedAt,'2026-10-01T00:00:00Z');assert.equal(draftStore.getItem(key),null);assert.match(host.textContent||'',/原转移已核对/)}finally{g.fetch=original;g.confirm=oldConfirm;await act(async()=>root.unmount());host.remove();draftStore.removeItem(key);window.happyDOM.abort();}});

