test('dated start-only and due-only exact point tasks export ICS without invalid zero-duration end',async()=>{const{SettingsDialog}=await import('../app/workspace-dialogs');const{importICS}=await import('../assets/importers');const state=fixture();state.records.push({...state.records[1],id:'due-point',data:{title:'Due point',dueDate:'2026-10-08',dueTime:'08:30',startInstant:'2026-10-08T00:30:00Z',timezone:'Asia/Shanghai'}},{...state.records[1],id:'start-point',data:{title:'Start point',startDate:'2026-10-08',startTime:'07:30',startInstant:'2026-10-07T23:30:00Z',dueDate:'',timezone:'Asia/Shanghai'}});const oldCreate=URL.createObjectURL;let blob:Blob|null=null;URL.createObjectURL=(value:Blob)=>{blob=value;return'blob:fixture'};const host=document.createElement('div');document.body.append(host as any);const root=createRoot(host as any);const actions:any={refresh:async()=>{},notify:()=>{}};try{await act(async()=>root.render(<SettingsDialog state={state} actions={actions} onClose={()=>{}}/>));await act(async()=>click(btn('导入与导出')));await act(async()=>click(btn('导出 ICS')));await settle();assert.ok(blob);const parsed=importICS(await(blob as unknown as Blob).text());const due=parsed.items.find(item=>item.title==='Due point')!,start=parsed.items.find(item=>item.title==='Start point')!;assert.equal(due.start.time,'00:30:00');assert.equal(start.start.time,'23:30:00');assert.equal(due.end,undefined);assert.equal(start.end,undefined)}finally{URL.createObjectURL=oldCreate;await act(async()=>root.unmount());host.remove();window.happyDOM.abort();}});

function formActions(state:Bootstrap,calls:any[]=[]){return{async save(base:AppRecord,patch:any,deleted=base.deleted,revision?:number){calls.push({base:structuredClone(base),patch:structuredClone(patch),revision});const current=state.records.find(r=>r.id===base.id)!;if(revision!==current.revision)throw Object.assign(new Error('模拟原基准冲突'),{status:409});const next={...current,data:{...current.data,...patch},deleted,revision:current.revision+1};state.records=state.records.map(r=>r.id===next.id?next:r);return next},async create(kind:any,data:any,id:any){const record={id,kind,data,ownerId:user.userId,revision:1,updatedAt:new Date().toISOString(),deleted:false,listId:null};state.records.push(record);return record},async refresh(){},notify(){}}as any}
