test('reminder lost-response input restores fixed snooze and reconciles committed receipt without another request',async()=>{const{useReminderActions}=await import('../app/reminder-actions');const key='qingdan:reminder-actions:'+encodeURIComponent(user.userId);draftStore.removeItem(key);const host=document.createElement('div');document.body.append(host as any);const root=createRoot(host as any);let writes=0,completed=0;let committed:any;g.fetch=async(path:string,init?:RequestInit)=>{assert.equal(path,'/api/reminders');const b=JSON.parse(init?.body as string);if(b.operation==='status')return Response.json({...committed,ok:true});committed=b;writes++;throw new TypeError('模拟稍后已保存但响应未知')};function Harness(){const controls=useReminderActions(user.userId,()=>completed++);return<><button onClick={()=>controls.act({id:'synthetic-alert',title:'Fixture',taskId:'task-ui'},'snooze')}>稍后测试</button>{controls.controls}</>}try{await act(async()=>root.render(<Harness/>));await act(async()=>click(btn('稍后测试')));await settle();const before=JSON.parse(draftStore.getItem(key)!).pending[0].input;assert.equal(before.until,committed.until);assert.ok(btn('核对并重试提醒操作'));await act(async()=>root.render(null));await act(async()=>root.render(<Harness/>));await act(async()=>click(btn('核对并重试提醒操作')));await settle();assert.equal(writes,1);assert.equal(completed,1);assert.equal(JSON.parse(draftStore.getItem(key)!).pending.length,0)}finally{await act(async()=>root.unmount());host.remove();draftStore.removeItem(key);window.happyDOM.abort();}});
test('calendar successive 100-row batches retain unconfirmed suffix and do not shift a committed unknown row twice',async()=>{const{useCalendarBatch}=await import('../app/calendar-batch');const key='qingdan:calendar-batch:'+user.userId;draftStore.removeItem(key);const tasks=Array.from({length:155},(_,i)=>({...fixture().records[1],id:'schedule-'+i,data:{...fixture().records[1].data,dueDate:'2026-10-08'}}));const host=document.createElement('div');document.body.append(host as any);const root=createRoot(host as any);let writes=0,lose=true;const actions:any={notify(){},async save(base:AppRecord,patch:any,_deleted:any,revision:number){const current=tasks.find(r=>r.id===base.id)!;assert.equal(revision,current.revision);writes++;Object.assign(current,{revision:current.revision+1,data:{...current.data,...patch}});if(base.id==='schedule-103'&&lose){lose=false;throw new Error('模拟提交结果未知')}return structuredClone(current)}};function Harness(){const batch=useCalendarBatch(user.userId,tasks,actions);return<>{batch.controls}<button onClick={()=>tasks.forEach(task=>batch.toggle(task))}>选择155条</button></>}try{await act(async()=>root.render(<Harness/>));await act(async()=>click(btn('选择155条')));assert.equal(JSON.parse(draftStore.getItem(key)!).records.length,155);await act(async()=>click(btn('应用下一批100条')));await settle();assert.equal(writes,100);assert.equal(JSON.parse(draftStore.getItem(key)!).records.length,55);await act(async()=>click(btn('应用批量排期')));await settle();assert.equal(writes,104);assert.equal(JSON.parse(draftStore.getItem(key)!).records.length,52);await act(async()=>root.render(null));await act(async()=>root.render(<Harness/>));assert.match(host.textContent||'',/52 条待处理/);await act(async()=>click(btn('应用批量排期')));await settle();assert.equal(writes,155);assert.equal(tasks.find(r=>r.id==='schedule-103')?.data.dueDate,'2026-10-09');assert.equal(tasks.every(r=>r.data.dueDate==='2026-10-09'),true);assert.equal(draftStore.getItem(key),null)}finally{await act(async()=>root.unmount());host.remove();draftStore.removeItem(key);window.happyDOM.abort();}});
test('unapplied visual organization filter conditions persist without changing the query silently',async()=>{const{RecordDialog}=await import('../app/workspace-dialogs');const{formDraftKey}=await import('../lib/form-drafts');const state=fixture(),key=formDraftKey(user.userId,'filter','new');draftStore.removeItem(key);const host=document.createElement('div');document.body.append(host as any);const root=createRoot(host as any);const actions=formActions(state);const render=()=>act(async()=>root.render(<RecordDialog type="filter" state={state} actions={actions} onClose={()=>{}}/>));try{await render();await act(async()=>type(host.querySelector<HTMLInputElement>('[aria-label="组织名称"]')!,'条件草稿'));const builder=host.querySelector('.filter-builder')!;const label=Array.from(builder.querySelectorAll('label')).find(l=>l.textContent?.trim()==='标签')!;await act(async()=>type(label.querySelector('input')as unknown as HTMLInputElement,'未应用标签'));await act(async()=>root.render(null));await render();assert.equal((Array.from(host.querySelectorAll('.filter-builder label')).find(l=>l.textContent?.trim()==='标签')?.querySelector('input')as unknown as HTMLInputElement).value,'未应用标签');assert.equal(host.querySelector<HTMLInputElement>('[aria-label="组织筛选表达式"]')?.value,'');await act(async()=>click(btn('将条件应用到表达式')));assert.equal(host.querySelector<HTMLInputElement>('[aria-label="组织筛选表达式"]')?.value,'#未应用标签')}finally{await act(async()=>root.unmount());host.remove();draftStore.removeItem(key);window.happyDOM.abort();}});
test('old organization create response cannot close the newly selected organization kind',async()=>{const{RecordDialog}=await import('../app/workspace-dialogs');const{formDraftKey}=await import('../lib/form-drafts');const state=fixture(),listKey=formDraftKey(user.userId,'list','new'),folderKey=formDraftKey(user.userId,'folder','new');draftStore.removeItem(listKey);draftStore.removeItem(folderKey);const host=document.createElement('div');document.body.append(host as any);const root=createRoot(host as any);let complete=()=>{},closed=0;const actions:any={...formActions(state),create:async(kind:string,data:any,id:string)=>new Promise(resolve=>{complete=()=>resolve({id,kind,data,revision:1,ownerId:user.userId,deleted:false})})};try{await act(async()=>root.render(<RecordDialog type="list" state={state} actions={actions} onClose={()=>closed++}/>));await act(async()=>type(host.querySelector<HTMLInputElement>('[aria-label="组织名称"]')!,'Old list'));await act(async()=>click(btn('保存')));const kind=host.querySelector('[aria-label="组织建立类型"]')as unknown as HTMLSelectElement;await act(async()=>{kind.value='folder';kind.dispatchEvent(new window.Event('change',{bubbles:true}))});await act(async()=>type(host.querySelector<HTMLInputElement>('[aria-label="组织名称"]')!,'New folder'));await act(async()=>complete());await settle();assert.equal(closed,0);assert.equal(host.querySelector<HTMLInputElement>('[aria-label="组织名称"]')?.value,'New folder');assert.equal(JSON.parse(draftStore.getItem(folderKey)!).fields.title,'New folder')}finally{complete();await act(async()=>root.unmount());host.remove();draftStore.removeItem(listKey);draftStore.removeItem(folderKey);window.happyDOM.abort();}});
