test('separated offline root restores only enabled last-account snapshot after real-shaped network failure, preserving quick draft',async()=>{const{default:OfflineRoot}=await import('../offline/root');const state=fixture();const offlineKey='qingdan:offline:'+encodeURIComponent(user.userId),quickKey='qingdan:quick-draft:'+user.userId;localStorage.setItem(offlineKey,JSON.stringify({version:1,accountId:user.userId,savedAt:new Date().toISOString(),data:state}));draftStore.setItem(quickKey,'离线刷新前的草稿');const original=g.fetch;g.fetch=async()=>{throw new TypeError('Synthetic offline')};const host=document.createElement('div');document.body.append(host as any);const root=createRoot(host as any);const services={async getSession(){return{version:1,accountId:user.userId,confirmedAt:new Date().toISOString(),active:true}},enabled:()=>true,async load(){return{data:state}},async probe(){throw Object.assign(new Error('Synthetic offline'),{code:'NETWORK_ERROR'})},async invalidate(){},goOnline(){throw new Error('Unexpected online redirect')}};try{await act(async()=>root.render(<OfflineRoot services={services}/>));await settle();assert.equal(host.querySelectorAll('.task-row').length,1);assert.match(host.querySelector('.offline-banner')?.textContent||'',/本地副本/);assert.equal(host.querySelector<HTMLTextAreaElement>('.quick-add textarea')?.value,'离线刷新前的草稿')}finally{g.fetch=original;await act(async()=>root.unmount());host.remove();draftStore.removeItem(quickKey);localStorage.removeItem(offlineKey);window.happyDOM.abort();}});
