test('settings clean controls follow remote refresh and dirty timezone keeps original revision until explicit rebase',async()=>{const{SettingsDialog}=await import('../app/workspace-dialogs');const state=fixture();let record:AppRecord={id:'settings:'+user.userId,ownerId:user.userId,kind:'settings',listId:null,data:{focusMinutes:25,timezone:'Etc/UTC'},revision:1,updatedAt:new Date().toISOString(),deleted:false};state.records.push(record);setupApi(state);const key='qingdan:form-draft:'+user.userId+':settings:preferences';draftStore.removeItem(key);const calls:any[]=[],actions=formActions(state,calls);const host=document.createElement('div');document.body.append(host as any);const root=createRoot(host as any);const oldConfirm=g.confirm;g.confirm=()=>true;const render=()=>act(async()=>root.render(<SettingsDialog state={state} settingsRecord={record} actions={actions} onClose={()=>{}}/>));try{await render();record={...record,revision:2,data:{...record.data,focusMinutes:50}};state.records=state.records.map(r=>r.id===record.id?record:r);await render();await act(async()=>click(btn('提醒与专注')));assert.equal(host.querySelector<HTMLInputElement>('[aria-label="番茄时长"]')?.value,'50');await act(async()=>click(btn('外观与偏好')));await act(async()=>type(host.querySelector<HTMLInputElement>('[aria-label="日期时区"]')!,'Asia/Tokyo'));record={...record,revision:3,data:{...record.data,focusMinutes:60,timezone:'Europe/London'}};state.records=state.records.map(r=>r.id===record.id?record:r);await render();await act(async()=>host.querySelector('[aria-label="日期时区"]')?.dispatchEvent(new window.FocusEvent('focusout',{bubbles:true})));await settle();assert.equal(calls[0].revision,2);assert.equal(record.data.timezone,'Europe/London');await act(async()=>click(btn('核对并重试原提交')));await settle();await act(async()=>click(btn('明确采用此云端基准')));assert.equal(host.querySelector<HTMLInputElement>('[aria-label="日期时区"]')?.value,'Asia/Tokyo');await act(async()=>click(btn('保存设置')));await settle();assert.equal(state.records.find(r=>r.id===record.id)?.data.timezone,'Asia/Tokyo');assert.equal(calls.at(-1).revision,3);assert.equal(state.records.find(r=>r.id===record.id)?.data.focusMinutes,60)}finally{g.confirm=oldConfirm;await act(async()=>root.unmount());host.remove();draftStore.removeItem(key);window.happyDOM.abort();}});
test('settings minute draft persists before blur and unknown save reconciles before committing newer input',async()=>{const state=fixture();setupApi(state);const key='qingdan:form-draft:'+user.userId+':settings:preferences';draftStore.removeItem(key);const original=g.fetch;let lose=true,block=false;g.fetch=async(path:string,init?:RequestInit)=>{const body=init?.body?JSON.parse(init.body as string):undefined;if(path==='/api/data'&&!body&&block)throw new TypeError('Synthetic offline read');const response=await original(path,init);if(lose&&body?.kind==='settings'){lose=false;block=true;throw new TypeError('Synthetic settings response lost')}return response};const host=document.createElement('div');document.body.append(host as any);const root=createRoot(host as any);try{await act(async()=>root.render(<Workspace user={user}/>));await settle();await act(async()=>click(host.querySelector('.header-settings')));await act(async()=>click(btn('提醒与专注')));await act(async()=>type(host.querySelector<HTMLInputElement>('[aria-label="番茄时长"]')!,'37'));await act(async()=>document.body.dispatchEvent(new window.KeyboardEvent('keydown',{key:'Escape',bubbles:true})));await act(async()=>click(host.querySelector('.header-settings')));await act(async()=>click(btn('提醒与专注')));assert.equal(host.querySelector<HTMLInputElement>('[aria-label="番茄时长"]')?.value,'37');await act(async()=>host.querySelector('[aria-label="番茄时长"]')?.dispatchEvent(new window.FocusEvent('focusout',{bubbles:true})));await settle();assert.equal(state.records.find(r=>r.kind==='settings')?.data.focusMinutes,37);await act(async()=>type(host.querySelector<HTMLInputElement>('[aria-label="番茄时长"]')!,'41'));block=false;await act(async()=>click(btn('核对并重试原提交')));await settle();assert.equal(host.querySelector<HTMLInputElement>('[aria-label="番茄时长"]')?.value,'41');await act(async()=>click(btn('保存设置')));await settle();assert.equal(state.records.filter(r=>r.kind==='settings').length,1);assert.equal(state.records.find(r=>r.kind==='settings')?.data.focusMinutes,41)}finally{g.fetch=original;await act(async()=>root.unmount());host.remove();draftStore.removeItem(key);window.happyDOM.abort();}});
test('unknown recurrence reply preserves newer interval and saves only after original operation reconciles',async()=>{const state=fixture();state.records[1].data.recurrence={start:{date:localDate(),timeZone:'Etc/UTC'},rule:{frequency:'daily',interval:1}};setupApi(state);const key='qingdan:form-draft:'+user.userId+':task:recurrence%3Atask-ui';draftStore.removeItem(key);const original=g.fetch;let lose=true,block=false;g.fetch=async(path:string,init?:RequestInit)=>{const body=init?.body?JSON.parse(init.body as string):undefined;if(path==='/api/data'&&!body&&block)throw new TypeError('Synthetic read offline');const response=await original(path,init);if(lose&&body?.data?.recurrence?.rule?.interval===2){lose=false;block=true;throw new TypeError('Synthetic recurrence response lost')}return response};const host=document.createElement('div');document.body.append(host as any);const root=createRoot(host as any);const interval=()=>Array.from(host.querySelectorAll('.modal input')).find(el=>el.getAttribute('max')==='1000')as unknown as HTMLInputElement;try{await act(async()=>root.render(<Workspace user={user}/>));await settle();await act(async()=>click(host.querySelector('.task-body')));await act(async()=>click(btn('每天 · 自定义')));await act(async()=>type(interval(),'2'));await act(async()=>click(btn('保存重复')));await settle();await act(async()=>type(interval(),'3'));assert.equal(btn('保存重复')?.disabled,true);block=false;await act(async()=>click(btn('核对并重试原提交')));await settle();assert.equal(interval().value,'3');await act(async()=>click(btn('保存重复')));await settle();assert.equal(state.records.find(r=>r.id==='task-ui')?.data.recurrence.rule.interval,3)}finally{g.fetch=original;await act(async()=>root.unmount());host.remove();draftStore.removeItem(key);window.happyDOM.abort();}});

