test('browser-local focus today and statistics use instant days including the seven-day boundary',async()=>{
 const originalTZ=process.env.TZ;const{addDays}=await import('../lib/types');
 try{for(const browserZone of['Asia/Shanghai','America/Los_Angeles'])for(const settingZone of['Asia/Shanghai','America/Los_Angeles']){process.env.TZ=browserZone;const today=localDate(),previous=addDays(today,-1),first=addDays(today,-6),beforeFirst=addDays(first,-1);const state=fixture();const base=state.records.find(r=>r.id==='task-ui')!;
 state.records.push({...base,id:'settings:'+user.userId,kind:'settings',listId:null,data:{timezone:settingZone}});
 for(const[id,day,time,seconds]of[['recent-a',previous,'16:30',1200],['recent-b',today,'00:30',1200],['boundary-a',beforeFirst,'16:30',600],['boundary-b',first,'00:30',600]]as const){const endedAt=day+'T'+time+':00.000Z';state.records.push({...base,id,kind:'focus',listId:null,data:{mode:'pomodoro',focusStatus:'finished',seconds,endedAt,startedAt:new Date(Date.parse(endedAt)-seconds*1000).toISOString()}})}
 for(const[id,day,time]of[['done-a',previous,'16:30'],['done-b',today,'00:30'],['done-boundary',beforeFirst,'16:30']]as const)state.records.push({...base,id,data:{...base.data,title:id,status:'done',completedAt:day+'T'+time+':00.000Z'}});
 setupApi(state);const host=document.createElement('div');document.body.append(host as any);const root=createRoot(host as any);
 try{await act(async()=>root.render(<Workspace user={user}/>));await settle();await act(async()=>click(host.querySelector('button[aria-label="专注"]')));const shanghai=browserZone==='Asia/Shanghai';assert.match(host.querySelector('.focus-history')?.textContent||'',shanghai?/今日专注40分钟2 次记录/:/今日专注0分钟0 次记录/);
 await act(async()=>click(host.querySelector('button[aria-label="统计"]')));assert.equal(host.querySelectorAll('.stat-cards article strong')[1]?.textContent,shanghai?'60分钟':'40分钟');assert.ok(host.querySelector(`[title="${shanghai?today:previous}：40分钟"]`));assert.ok(host.querySelector(`[title="${shanghai?today:previous}：2项"]`));assert.equal(host.querySelectorAll('.stat-cards article strong')[0]?.textContent,shanghai?'3项':'2项');
 const range=host.querySelector('[aria-label="统计范围"]')as unknown as HTMLSelectElement;await act(async()=>{range.value='30';range.dispatchEvent(new window.Event('change',{bubbles:true}))});assert.equal(host.querySelectorAll('.stat-cards article strong')[1]?.textContent,'60分钟');
 }finally{await act(async()=>root.unmount());host.remove();window.happyDOM.abort()}
 }}finally{if(originalTZ===undefined)delete process.env.TZ;else process.env.TZ=originalTZ}
});

test('detail attachment XHR sends the active standalone CSRF and account headers',async()=>{const state=fixture();setupApi(state);const{configureSession}=await import('../lib/client');configureSession('synthetic-upload-csrf');const previous=g.XMLHttpRequest;let sent:any=null;class CaptureXHR{upload={onprogress:null};onload:any;onerror:any;status=200;responseText='{}';headers:Record<string,string>={};open(method:string,path:string){assert.equal(method,'POST');assert.equal(path,'/api/attachments')}setRequestHeader(key:string,value:string){this.headers[key]=value}send(body:FormData){sent={headers:this.headers,body}}abort(){}}g.XMLHttpRequest=CaptureXHR;const host=document.createElement('div');document.body.append(host as any);const root=createRoot(host as any);try{await act(async()=>root.render(<Workspace user={user}/>));await settle();await act(async()=>click(host.querySelector('.task-body')));const input=host.querySelector<HTMLInputElement>('.detail-panel input[type=file]')!;assert.ok(input);const file=new File(['synthetic ordinary attachment'],'synthetic.txt',{type:'text/plain'});Object.defineProperty(input,'files',{value:[file],configurable:true});await act(async()=>input.dispatchEvent(new window.Event('change',{bubbles:true})));for(let attempt=0;attempt<20&&!sent;attempt++)await settle();assert.ok(sent);assert.equal(sent.headers['x-qingdan'],'1');assert.equal(sent.headers['x-qingdan-expected-account'],user.userId);assert.equal(sent.headers['x-qingdan-csrf'],'synthetic-upload-csrf');assert.equal(sent.body.get('recordId'),'task-ui')}finally{await act(async()=>root.unmount());host.remove();window.happyDOM.abort();g.XMLHttpRequest=previous;configureSession('')}});
